"""Grounded literature-only deliverability path.

This module deliberately does not consume genome/FBA evidence.  It can
therefore be compared with silver labels generated by those mechanisms
without leaking the silver answer into the prediction path.
"""
from collections import Counter
from dataclasses import asdict, dataclass
import re
from typing import Callable

from .abstain import decide
from .extract import LLMClient, extract_judgment
from .retrieval import fetch_evidence
from .rubric import deliverable_now
from .schema import Candidate, Chassis, Decision, RelationType


_PMID_RE = re.compile(r"\bPMID\s+(\d+)\b", re.I)


@dataclass
class LiteratureAssessment:
    pair_id: str
    status: str
    retrieved_count: int
    grounded_runs: int
    p_raw: float | None
    decision: str
    semantic_source: str
    precursor_available: str
    evidence_pmids: str
    denovo_support: float = 0.0
    biotransform_support: float = 0.0
    non_native_support: float = 0.0
    mean_confidence: float = 0.0
    engineering_support: float = 0.0
    synthesis_path: dict | None = None

    def to_dict(self) -> dict:
        return asdict(self)


def _pmids(snippets: list[str]) -> set[str]:
    return {m.group(1) for text in snippets for m in _PMID_RE.finditer(text)}


def assess_literature(
    candidate: Candidate,
    chassis: Chassis,
    client: LLMClient,
    *,
    pair_id: str | None = None,
    k: int = 3,
    tau_low: float = 0.25,
    tau_high: float = 0.75,
    offline: bool = False,
    cache_dir=None,
    retriever: Callable = fetch_evidence,
    blocked_pmids: set[str] | None = None,
) -> LiteratureAssessment:
    """Retrieve, extract and aggregate only PMID-grounded judgments.

    Empty retrieval and ungrounded model output become ``abstain`` rather
    than a biological negative.
    """
    pid = pair_id or f"{candidate.id}__{chassis.id}"
    try:
        snippets = retriever(
            candidate,
            chassis,
            offline=offline,
            cache_dir=cache_dir,
            raise_on_error=True,
            blocked_pmids=blocked_pmids,
        )
    except Exception:
        return LiteratureAssessment(
            pid, "retrieval_error", 0, 0, None,
            Decision.ABSTAIN.value, "", "", "",
        )
    allowed_pmids = _pmids(snippets)
    if not snippets or not allowed_pmids:
        return LiteratureAssessment(
            pid, "no_retrieved_evidence", len(snippets), 0, None,
            Decision.ABSTAIN.value, "", "", "",
        )

    judgments = [
        extract_judgment(
            client,
            candidate,
            chassis,
            retrieved_snippets=snippets,
            literature_only=True,
        )
        for _ in range(k)
    ]

    grounded = []
    cited_pmids: set[str] = set()
    for judgment in judgments:
        cited = {
            str(e.citation_pmid)
            for e in judgment.evidence
            if e.citation_pmid and str(e.citation_pmid) in allowed_pmids
        }
        informative = any(
            e.relation_type != RelationType.NOT_REPORTED
            and e.citation_pmid
            and str(e.citation_pmid) in allowed_pmids
            for e in judgment.evidence
        )
        if informative:
            grounded.append(judgment)
            cited_pmids.update(cited)

    if not grounded:
        return LiteratureAssessment(
            pid, "retrieved_but_insufficient", len(snippets), 0, None,
            Decision.ABSTAIN.value, "", "", "",
        )

    labels = [
        deliverable_now(
            j.semantic_source,
            j.precursor_available,
            j.engineering_required,
        )
        for j in grounded
    ]
    p_raw = sum(labels) / len(labels)
    source = Counter(j.semantic_source.value for j in grounded).most_common(1)[0][0]
    precursor = Counter(j.precursor_available.value for j in grounded).most_common(1)[0][0]
    class_support = {
        source_name: sum(
            j.raw_confidence for j in grounded if j.semantic_source.value == source_name
        ) / len(grounded)
        for source_name in ("denovo", "biotransform", "non_native")
    }
    return LiteratureAssessment(
        pid,
        "ok",
        len(snippets),
        len(grounded),
        p_raw,
        decide(p_raw, tau_low, tau_high).value,
        source,
        precursor,
        ";".join(sorted(cited_pmids)),
        class_support["denovo"],
        class_support["biotransform"],
        class_support["non_native"],
        sum(j.raw_confidence for j in grounded) / len(grounded),
        sum(
            j.raw_confidence for j in grounded if j.engineering_required
        ) / len(grounded),
    )
